import React, { useState, useEffect } from "react";
import { View, FlatList, Text } from "react-native";
import AsyncStorage from "@react-native-async-storage/async-storage";
import { Nota } from "./src/componentes/Nota";
import NotaEditor from "./src/componentes/NotaEditor";



export default function App() {
  const [notas, setNotas] = useState([]);
  const [notaEditando, setNotaEditando] = useState(null);

  // Função para migrar notas antigas para o novo formato
  const migrarNotasAntigas = async () => {
    try {
      const todasChaves = await AsyncStorage.getAllKeys();
      const todasNotas = await AsyncStorage.multiGet(todasChaves);

      let notasMigradas = false;

      for (const [chave, valor] of todasNotas) {
        // Se o valor não é um JSON válido, é uma nota antiga
        try {
          JSON.parse(valor);
        } catch (e) {
          // É uma nota antiga - migrar para novo formato
          const novaNota = {
            texto: valor,
            categoria: "Pessoal"
          };
          await AsyncStorage.setItem(chave, JSON.stringify(novaNota));
          notasMigradas = true;
          console.log("Nota migrada:", chave);
        }
      }

      if (notasMigradas) {
        console.log("Migração de notas completada");
      }
    } catch (error) {
      console.error("Erro na migração:", error);
    }
  };

  const mostraNotas = async () => {
    try {
      // Primeiro migra notas antigas
      await migrarNotasAntigas();

      const todasChaves = await AsyncStorage.getAllKeys();
      const todasNotas = await AsyncStorage.multiGet(todasChaves);

      console.log("Todas as chaves no storage:", todasChaves);
      console.log("Todas as notas do storage:", todasNotas);

      const notasFormatadas = todasNotas
        .filter(([chave, valor]) => {
          const isValid = valor !== null && valor !== undefined && valor.trim() !== "";
          console.log(`Chave: ${chave}, Valor: ${valor}, Válida: ${isValid}`);
          return isValid;
        })
        .map(([chave, valor]) => {
          try {
            const notaParseada = JSON.parse(valor);
            console.log("Nota parseada:", notaParseada);
            return {
              id: chave,
              texto: notaParseada.texto,
              categoria: notaParseada.categoria || "Pessoal"
            };
          } catch (e) {
            console.log("Erro ao parsear nota, mantendo formato antigo:", e);
            return {
              id: chave,
              texto: valor,
              categoria: "Pessoal"
            };
          }
        });

      console.log("Notas formatadas para exibição:", notasFormatadas);
      setNotas(notasFormatadas);
    } catch (error) {
      console.error("Erro ao carregar notas:", error);
    }
  };

  const editarNota = (nota) => {
    console.log("Editando nota:", nota);
    setNotaEditando(nota);
  };

  const cancelarEdicao = () => {
    setNotaEditando(null);
  };

  useEffect(() => {
    mostraNotas();
  }, []);

  return (
    <View style={{ flex: 1, paddingTop: 50 }}>
      <Text style={{ fontSize: 24, fontWeight: "bold", textAlign: "center", marginBottom: 20 }}>
        Minhas Notas
      </Text>

      <FlatList
        data={notas}
        keyExtractor={(item) => item.id}
        renderItem={({ item }) => (
          <Nota 
            item={item} 
            onPress={() => editarNota(item)}
          />
        )}
        ListEmptyComponent={
          <Text style={{ textAlign: "center", marginTop: 20, padding: 16, color: "#666" }}>
            Nenhuma nota encontrada. Clique no + para criar uma nova nota.
          </Text>
        }
      />

      <NotaEditor 
        mostraNotas={mostraNotas}
        notaEditando={notaEditando}
        onCancelarEdicao={cancelarEdicao}
      />
    </View>
  );
}
